import { betaZodTool } from "@anthropic-ai/sdk/helpers/beta/zod";
import { z } from "zod";
const getWeather = betaZodTool({
  name: "get_weather",
  description: "Get current weather for a location",
  inputSchema: z.object({
    location: z.string().describe("City and state, e.g., San Francisco, CA"),
    unit: z.enum(["celsius", "fahrenheit"]).optional(),
  }),
  run: async (input) => `72°F and sunny in ${input.location}`,
});

const params = {
  model: "claude-opus-5-5", max_tokens: 16000, max_iterations: 8, stream: false as const,
  output_config: { effort: "medium" as const },
  cache_control: { type: "ephemeral" as const },
  betas: ["server-side-fallback-2026-07-01"], fallbacks: "default" as const,
  system: [{ type: "text" as const, text: SYSTEM, cache_control: { type: "ephemeral" as const } }],
  tools: [strictTool], messages: [{ role: "user" as const, content: "..." }],
} satisfies BetaToolRunnerParams;

let total = { in: 0, out: 0, cw5m: 0, cw1h: 0, cr: 0 };
for await (const message of runner) {
  const u = message.usage;
  total.in += u.input_tokens; total.out += u.output_tokens;
  total.cw5m += u.cache_creation?.ephemeral_5m_input_tokens ?? 0;
  total.cw1h += u.cache_creation?.ephemeral_1h_input_tokens ?? 0;
  total.cr += u.cache_read_input_tokens ?? 0;
}

const streamingRunner = client.beta.messages.toolRunner({ ...params, stream: true });
for await (const stream of streamingRunner) {
  stream.on("text", (d) => process.stdout.write(d));
  const message = await stream.finalMessage();
  console.log(message.stop_reason, message.usage.output_tokens);
}

import { zodOutputFormat } from "@anthropic-ai/sdk/helpers/zod";
const response = await client.messages.parse({
  model: "claude-opus-5-5", max_tokens: 16000,
  messages: [{ role: "user", content: "..." }],
  output_config: { format: zodOutputFormat(ContactInfoSchema) },
});
// parsed_output is null if parsing failed - assert or guard
console.log(response.parsed_output!.name);

const response = await client.messages.create({
  model: "claude-opus-5-5",
  max_tokens: 16000,
  thinking: { type: "adaptive", display: "summarized" }, // display opt-in
  output_config: { effort: "high" }, // low | medium | high | xhigh | max
  messages: [{ role: "user", content: "..." }],
});

const response = await client.messages.create({
  model: "claude-opus-5-5",
  max_tokens: 16000,
  tools: tools.map((tool) => ({ ...tool, strict: true })), // schemas must set additionalProperties: false
  messages: [{ role: "user", content: "What's the weather in Paris? Use the get_weather tool." }],
});
// auto does not guarantee a call - check for a tool_use block and re-prompt if none came back

const response = await client.beta.messages.create({
  model: "claude-opus-5-5",
  max_tokens: 16000,
  betas: ["server-side-fallback-2026-07-01"],
  fallbacks: "default",
  messages: [{ role: "user", content: "..." }],
});
const fallbackRan = (response.usage.iterations ?? []).some((e) => e.type === "fallback_message");
if (response.stop_reason === "refusal") console.log(response.stop_details?.category);

const runner = client.beta.messages.toolRunner({
  model: "claude-opus-5-5", max_tokens: 16000,
  cache_control: { type: "ephemeral" }, // automatic breakpoint for the growing tail
  system: [{ type: "text", text: FROZEN_SYSTEM, cache_control: { type: "ephemeral" } }],
  tools: sortedTools, // deterministic order, fixed for the session
  messages: [{ role: "user", content: [
    { type: "text", text: transcriptJson, cache_control: { type: "ephemeral" } }, // shared, stable bytes
    { type: "text", text: taskInstruction },                                      // varying, no marker
  ] }],
});

try {
  const response = await client.messages.create({...});
} catch (error) {
  if (error instanceof Anthropic.BadRequestError) {
    console.error("Bad request:", error.message);
  } else if (error instanceof Anthropic.AuthenticationError) {
    console.error("Invalid API key");
  } else if (error instanceof Anthropic.RateLimitError) {
    console.error("Rate limited - retry later");
  } else if (error instanceof Anthropic.APIError) {
    console.error(`API error ${error.status}:`, error.message);
  }
}

const PRICE = { in: 4, out: 20, cacheRead: 0.2, cacheWrite5m: 5, cacheWrite1h: 8 }; // USD per MTok, claude-opus-5-5
function usd(u: Anthropic.Beta.BetaUsage): number {
  const w5 = u.cache_creation?.ephemeral_5m_input_tokens ?? (u.cache_creation_input_tokens ?? 0);
  const w1 = u.cache_creation?.ephemeral_1h_input_tokens ?? 0;
  return (u.input_tokens * PRICE.in + w5 * PRICE.cacheWrite5m + w1 * PRICE.cacheWrite1h
    + (u.cache_read_input_tokens ?? 0) * PRICE.cacheRead + u.output_tokens * PRICE.out) / 1_000_000;
}

import { query, tool, createSdkMcpServer } from '@anthropic-ai/claude-agent-sdk';
import { z } from 'zod';

const lookup = tool('lookup', 'Look up a record', { id: z.string() },
  async ({ id }) => ({ content: [{ type: 'text', text: `record ${id}` }] }));
const mytools = createSdkMcpServer({ name: 'mytools', version: '1.0.0', tools: [lookup] });

for await (const m of query({
  prompt: 'Find record 42',
  options: {
    mcpServers: { mytools },
    tools: [],                          // no built-in tools in context
    allowedTools: ['mcp__mytools__*'],  // auto-approve only our server
    permissionMode: 'dontAsk',          // deny anything else; canUseTool never called
    settingSources: [],                 // ignore .claude/settings.json allow rules
    model: 'claude-opus-5-5',
    maxTurns: 10,
    cwd: 'C:/Users/firda/монтаж',
  },
})) { /* ... */ }

for await (const m of query({ prompt, options })) {
  if (m.type === 'result') {
    if (m.subtype === 'success') console.log(m.result);
    else console.error(m.subtype, m.errors);
  }
}

for await (const m of query({ prompt, options: { includePartialMessages: true } })) {
  if (m.type === 'stream_event' && m.event.type === 'content_block_delta' && m.event.delta.type === 'text_delta')
    process.stdout.write(m.event.delta.text);
}

export const ClipSchema = z.object({
  src_start: z.number().min(0),
  src_end: z.number().positive(),
  speed: z.number().min(0.25).max(4).default(1),
  crop: z.enum(["center", "auto_face"]).default("center"),
}).refine((c) => c.src_end > c.src_start, { message: "src_end must be greater than src_start" });

export const OutputSchema = z.object({
  id: z.string().regex(/^[a-zA-Z0-9_-]+$/, "id must be filename-safe"),
  aspect: AspectSchema,
  target_duration: z.number().positive().optional(),
  clips: z.array(ClipSchema).min(1),
  captions: z.object({ enabled: z.boolean(), language: z.string().optional(), style: z.string().optional() }).default({ enabled: false }),
  titles: z.array(TitleSchema).default([]),
  music: z.object({ enabled: z.boolean() }).default({ enabled: false }),
  transitions: z.enum(["cut"]).default("cut"),
});

export const TranscriptSchema = z.object({
  language: z.string(),
  segments: z.array(z.object({
    start: z.number(), end: z.number(), text: z.string(),
    words: z.array(WordSchema),
    lang: z.string().optional(),
  })),
});

export async function extractFrame(video: string, t: number, file: string, width = 640) {
  await ffmpeg(["-ss", t.toFixed(3), "-i", video, "-frames:v", "1", "-vf", `scale=${width}:-2`, "-q:v", "3", file]);
  return file;
}

