export interface PlanOptions { prompt: string; preset?: string; backend?: BackendChoice; model?: string; effort?: Effort; limits?: Partial<PlanLimits>; allowFallback?: boolean; dryRun?: boolean; onEvent?: (e: PlanEvent) => void; deps?: Partial<PlanDeps> }
export async function plan(jobId: string, media: Media, opts: PlanOptions): Promise<PlanReport & { edl: Edl; partial: boolean }>
export async function runPlanner(ctx: PlanContext, task: PlanTask, backend: PlannerBackend, limits: PlanLimits, deps: PlanDeps, onEvent?): Promise<{ session: PlanSession; result: BackendResult }>  // shared by plan() and stage-5 revise()
export class PlanError extends Error { constructor(message: string, readonly report?: PlanReport) }
export const DEFAULT_LIMITS: PlanLimits = { maxIterations: 24, maxRounds: 3, maxNudges: 2, maxSubmitAttempts: 4, maxValidateCalls: 12, maxPreviewFrames: 12, maxTranscriptCalls: 20, maxSceneCalls: 10, maxToolCalls: 60, maxUsd: 3, maxOutputTokens: 16000, raisedOutputTokens: 20000 }

export interface PlanContext { jobId: string; dir: string; media: Media; transcript: Transcript; scenes: Scenes; highlights: Highlights; preset: Preset; words: Word[]; boundaries: number[]; gaps: Array<[number, number]>; warnings: string[] }
export async function loadPlanContext(jobId: string, presetName?: string): Promise<PlanContext>
export function phraseAt(ctx, t): number | null; export function sceneAt(ctx, t): number | null; export function frameForScene(ctx, sceneId): string | null  // frames/shot_NNN.jpg if it exists, else null (scene idx == shot idx only with the stub provider — documented assumption)

export const PROMPT_VERSION = 1
export const SYSTEM_PROMPT: string  // frozen; includes the static tool budget numbers from DEFAULT_LIMITS
export type PlanTask = { mode: 'plan'; instruction: string } | { mode: 'revise'; instruction: string; currentEdl: Edl }
export function buildTaskBlock(task: PlanTask): string  // deterministic; revise mode embeds stableStringify(currentEdl)
export const NUDGE_MESSAGE = 'You stopped without an accepted EDL. Call validate_edl, fix every error, then call submit_edl now. Do not explain.'
export function stableStringify(v: unknown): string  // sorted keys, no whitespace

export type ToolOutput = { text: string; image?: { base64: string; mediaType: 'image/jpeg' }; isError?: boolean }
export interface PlannerToolSpec<S extends z.ZodObject<any> = z.ZodObject<any>> { name: string; description: string; inputSchema: S; run(input: z.infer<S>, ctx: { signal?: AbortSignal }): Promise<ToolOutput> }
export const TranscriptRangeInput, SceneDetailsInput, PreviewFrameInput, EdlToolInput (= z.object({ edl: EdlSubmitSchema })), EdlSubmitSchema
export function createPlannerTools(session: PlanSession): PlannerToolSpec[]  // ALWAYS returned sorted by name: get_scene_details, get_transcript_range, preview_frame, submit_edl, validate_edl
export function toolJsonSchema(spec: PlannerToolSpec): Record<string, unknown>  // z.toJSONSchema(spec.inputSchema, { reused: 'ref' }) then sanitizeToolSchema
export function sanitizeToolSchema(schema): Record<string, unknown>  // deletes $schema, default, pattern, minimum, maximum, exclusiveMinimum/Maximum, minLength, maxLength, minItems>1, format not in the allowed set; forces additionalProperties:false on every object; recursive

export interface PlanDeps { extractFrame: (video: string, t: number, file: string, width?: number) => Promise<string>; readFileBase64: (file: string) => Promise<string>; exists: (f: string) => Promise<boolean> }
export const defaultDeps: PlanDeps  // wraps src/understand/shots.ts extractFrame + fs
export interface SubmitAttempt { n: number; ok: boolean; errors: PlanIssue[]; warnings: PlanIssue[]; repairs: string[]; edl?: Edl /* repaired, parsed */ }
export interface ToolCallRecord { i: number; tool: string; input: unknown; ok: boolean; ms: number; resultChars: number; image?: boolean }
export class PlanSession { constructor(ctx: PlanContext, limits: PlanLimits, deps: PlanDeps); readonly trace: ToolCallRecord[]; readonly attempts: SubmitAttempt[]; accepted: Edl | null; counters: Record<string, number>; get submitExhausted(): boolean; bestAttempt(): SubmitAttempt | undefined /* fewest errors, latest wins ties */; record(tool, input, fn): Promise<ToolOutput> /* timing + trace + limit checks */ }

export type IssueCode = 'E_SCHEMA'|'E_RANGE'|'E_WORD_CUT'|'E_BOUNDARY'|'E_MIN_CLIP'|'E_DUPLICATE'|'E_DURATION'|'E_TITLE_RANGE'|'W_SOFT_BOUNDARY'|'W_LONG_CLIP'|'W_OVERLAP'|'W_SPEED_ON_SPEECH'|'W_NO_CAPTION_LANG'|'W_TARGET_MISSING'|'W_NO_SPEECH'
export interface PlanIssue { code: IssueCode; path: string /* 'outputs[0].clips[2].src_end' */; message: string; suggested?: number }
export interface PlanValidation { ok: boolean; errors: PlanIssue[]; warnings: PlanIssue[]; edl?: Edl; outputs: Array<{ id: string; clips: number; duration: number; target_duration?: number }> }
export const RULES = { boundaryTol: 0.15, snapMax: 0.4, softGapMin: 0.5, wordTol: 0.03, durationTol: (t) => Math.max(2, 0.1 * t) }
export function boundaryCandidates(ctx: PlanContext): number[]  // {0, duration} ∪ phrase starts/ends ∪ scene starts/ends, rounded 3dp, sorted unique
export function validatePlan(input: unknown, ctx: PlanContext, opts?: { strictBoundaries?: boolean }): PlanValidation
export function autoRepair(edl: Edl, ctx: PlanContext): { edl: Edl; repairs: string[] }  // snapClipsToWords(0.4) then snapToBoundaries(0.4); drops nothing, only moves edges
export function snapToBoundaries(clips: Clip[], ctx: PlanContext, maxShift?: number): { clips: Clip[]; notes: string[] }
export function clipsDuration(clips: Clip[]): number

export type BackendChoice = 'auto'|'anthropic'|'agent-sdk'|'mock'
export type Effort = 'low'|'medium'|'high'|'xhigh'|'max'
export interface BackendRequest { system: string; overview: string; task: string; tools: PlannerToolSpec[]; session: PlanSession; model: string; effort: Effort; limits: PlanLimits; onEvent?: (e: PlanEvent) => void; signal?: AbortSignal }
export type StopReason = 'submitted'|'attempts_exhausted'|'end_turn'|'max_iterations'|'max_tokens'|'refusal'|'budget'|'error'
export interface UsageTotals { requests: number; input_tokens: number; output_tokens: number; thinking_tokens: number; cache_read_input_tokens: number; cache_creation_5m: number; cache_creation_1h: number; per_iteration: IterationUsage[] }
export interface IterationUsage { i: number; model: string; input_tokens; output_tokens; cache_read; cache_write; stop_reason: string | null; tools: string[]; usd: number }
export interface BackendResult { stop: StopReason; usage: UsageTotals; usd: number; estimated: boolean; nudges: number; rounds: number; finalText?: string; error?: string; notes: string[] }
export interface PlannerBackend { readonly name: 'anthropic'|'agent-sdk'|'mock'; readonly note: string; run(req: BackendRequest): Promise<BackendResult> }
export type PlanEvent = { type: 'iteration'; i: number; usd: number } | { type: 'tool'; name: string; input: unknown; ok: boolean; ms: number } | { type: 'submit'; attempt: number; ok: boolean; errors: number } | { type: 'note'; text: string }

export class AnthropicBackend implements PlannerBackend { constructor(opts: { apiKey?: string; client?: Anthropic /* injectable for tests */; strictTools?: boolean /* default true */; fallbacks?: boolean /* default false */ }) }
export function toRunnableTool(spec: PlannerToolSpec, strict: boolean): BetaRunnableTool<any>  // { ...betaZodTool({ name, description, inputSchema, run: adaptRun(spec) }), input_schema: toolJsonSchema(spec), ...(strict ? { strict: true as const } : {}) }
export function buildParams(req, maxTokens, messages): BetaToolRunnerParams  // object literal with `stream: false as const` + satisfies (TS overload gotcha)
export function assistantToolNames(m: BetaMessage): string[]

export class AgentSdkBackend implements PlannerBackend { constructor(opts?: { pathToClaudeCodeExecutable?: string; env?: NodeJS.ProcessEnv }) }
export function toSdkTool(spec: PlannerToolSpec): SdkMcpToolDefinition  // tool(spec.name, spec.description, spec.inputSchema.shape, handler, { alwaysLoad: true }); handler returns { content: [{type:'text',text}, {type:'image', data, mimeType:'image/jpeg'}?], isError? }
export const MCP_SERVER_NAME = 'vedit'  // tools appear as mcp__vedit__<name>; the adapter appends a 'tool names are prefixed mcp__vedit__' line to the system prompt

export type MockTurn = { calls: Array<{ tool: string; input: unknown }> } | { text: string }  // one assistant message each
export type MockScript = MockTurn[] | ((history: Array<{ tool: string; input: unknown; output: ToolOutput }>, round: number) => MockTurn | undefined)
export class MockBackend implements PlannerBackend { constructor(script: MockScript, opts?: { usagePerTurn?: Partial<IterationUsage> }) }

export interface LoopState { iterations: number; rounds: number; nudges: number; raisedMaxTokens: boolean; usd: number; accepted: boolean; submitExhausted: boolean; lastStop: string | null }
export type NextAction = { kind: 'stop'; stop: StopReason } | { kind: 'nudge' } | { kind: 'retry_higher_max_tokens' }
export function nextAction(state: LoopState, limits: PlanLimits): NextAction
export function overBudget(state, limits): boolean

export async function revise(jobId: string, media: Media, opts: PlanOptions & { currentEdl?: Edl }): Promise<PlanReport & { edl: Edl; diff: EdlDiff; affected: string[]; partial: boolean }>
export interface EdlDiff { added: string[]; removed: string[]; changed: Array<{ id: string; fields: string[] }>; unchanged: string[] }
export function diffEdl(before: Edl, after: Edl): EdlDiff  // per-output deep compare on stableStringify of each output

export const RefSchema = z.string().describe('phrase or scene id, optionally with edge: "p12", "s3", "p12.end", "s3.start"; never seconds');
export const DraftClipSchema = z.object({ start: RefSchema, end: RefSchema, speed: z.number().optional(), crop: z.enum(['center','auto_face']).optional(), note: z.string().optional() });
export const DraftTitleSchema = z.object({ at: z.number(), duration: z.number().optional(), text: z.string(), style: z.string().optional() });
export const DraftOutputSchema = z.object({ id: z.string(), aspect: z.enum(['9:16','1:1','16:9']), target_duration: z.number().optional(), hook: z.string().optional(), clips: z.array(DraftClipSchema), captions: z.object({ enabled: z.boolean(), language: z.string().optional(), style: z.string().optional() }), titles: z.array(DraftTitleSchema), music: z.object({ enabled: z.boolean() }) });
export const DraftBriefSchema = z.object({ outputs_requested: z.number().optional(), target_duration_s: z.number().optional(), aspect: z.enum(['9:16','1:1','16:9']).optional(), captions_language: z.string().optional(), style_words: z.array(z.string()) });
export const PlanDraftSchema = z.object({ brief: DraftBriefSchema, outputs: z.array(DraftOutputSchema), reasoning: z.string() });
export type PlanDraft = z.infer<typeof PlanDraftSchema>; export type DraftOutput; export type DraftClip;
export const IssueCodeSchema = z.enum(['invalid_json','schema','unknown_ref','raw_time','empty_clip','out_of_media','cuts_word','bad_speed','no_clips','no_outputs','bad_id','duplicate_id','count_mismatch','duration_off','title_outside','captions_no_language','speech_speed','overlap']);
export const PlanIssueSchema = z.object({ severity: z.enum(['error','warning']), code: IssueCodeSchema, output: z.string().optional(), clip: z.number().int().optional(), message: z.string(), suggestion: z.string().optional() });
export type PlanIssue = z.infer<typeof PlanIssueSchema>;
export const PlanUsageSchema = z.object({ input_tokens: z.number(), output_tokens: z.number(), cache_read_input_tokens: z.number(), cache_creation_input_tokens: z.number() });
export const ToolCallRecordSchema = z.object({ name: z.string(), input: z.unknown(), ok: z.boolean(), ms: z.number(), summary: z.string() });
export const PlanReportSchema = z.object({ status: z.enum(['ok','partial','failed']), backend: z.string(), backend_note: z.string().optional(), model: z.string(), effort: z.string(), mode: z.enum(['full','compact']), context_tokens_est: z.number(), instruction: z.string(), preset: z.string(), calls: z.number().int(), repairs: z.number().int(), tool_calls: z.array(ToolCallRecordSchema), usage: PlanUsageSchema, usd: z.number(), priced: z.boolean(), fixed: z.array(PlanIssueSchema), issues: z.array(PlanIssueSchema), warnings: z.array(z.string()), draft: PlanDraftSchema.nullable(), error: z.string().optional(), wall_seconds: z.number() });
export type PlanReport = z.infer<typeof PlanReportSchema>;
export const EdlDiffSchema = z.object({ added: z.array(z.string()), removed: z.array(z.string()), changed: z.array(z.object({ id: z.string(), fields: z.array(z.string()) })), unchanged: z.array(z.string()) });
export const ReviseReportSchema = PlanReportSchema.extend({ edit: z.string(), diff: EdlDiffSchema, affected: z.array(z.string()), previous_edl: z.string() });

export interface Phrase { id: string; index: number; start: number; end: number; lang: string; text: string; words: Word[] }
export interface SceneRef { id: string; index: number; start: number; end: number; description: string; objects: string[]; people_count: number; emotion: string; shot_type: string; quality_score: number; phrases: string[] }
