export function buildPlanContext(input: { media: Media; transcript?: Transcript; scenes?: Scenes; highlights?: Highlights; preset: Preset; jobDir: string; compactAbove?: number /* default 40_000 tokens */ }): PlanContext
export function renderPack(ctx: Omit<PlanContext,'packText'|'tokenEstimate'>): string   // JSON.stringify of an object built in fixed key order, numbers rounded to 2 decimals, no timestamps/ids/paths; identical bytes for identical inputs
