export function nearestBoundaryRef(t: number, side: 'start' | 'end', ctx: PlanContext, tol = 0.03): string | null
export function draftFromEdl(edl: Edl, ctx: PlanContext): PlanDraft   // clips whose edges match a boundary within tol become ids, others become 't12.400'; brief filled from the EDL (outputs_requested = outputs.length)

export interface ResolvedOutput { id: string; output: z.input<typeof OutputSchema> | null; expected_duration: number; issues: PlanIssue[] }
export interface ResolvedDraft { edl: z.input<typeof EdlSchema> | null /* null when no output is valid */; outputs: ResolvedOutput[]; issues: PlanIssue[] /* all, flattened */; errors: number; warnings: number }
export function resolveDraft(draft: PlanDraft, ctx: PlanContext, opts: { mode: 'plan' | 'revise'; currentEdl?: Edl; maxSnap?: number /* 0.4 */; durationTolerance?: { warn: number; error: number } /* fractions 0.10 / 0.25, floors 2 s / 5 s */ }): ResolvedDraft
export function formatIssuesForModel(issues: PlanIssue[]): string   // compact JSON list the repair message and validate_edl both return

export interface ToolResult { text: string; images?: Array<{ mediaType: 'image/jpeg'; base64: string }>; isError?: boolean }
export interface PlannerTool<I = any> { name: string; description: string; inputShape: z.ZodRawShape; run(input: I): Promise<ToolResult> }
export interface ToolDeps { extractFrame?: (t: number) => Promise<Buffer> /* default: extractFrame() from understand/shots.ts into <jobDir>/frames/preview_<ms>.jpg, reused if present */; frameBudget?: number /* 6 */; maxToolCalls?: number /* 12 per job */; onCall?: (rec: ToolCallRecord) => void }
export function makePlannerTools(ctx: PlanContext, deps: ToolDeps = {}): PlannerTool[]   // returned sorted by name: get_scene_details, get_transcript_range, preview_frame, validate_edl
export class ToolBudgetError extends Error {}

export const PRICES_AS_OF = '2026-10-06'
export const PRICES: Record<string, { in: number; out: number; cacheRead: number; cacheWrite5m: number; cacheWrite1h: number; batchIn?: number; batchOut?: number }> = { 'claude-opus-5-5': { in: 4, out: 20, cacheRead: 0.2, cacheWrite5m: 5, cacheWrite1h: 8, batchIn: 2, batchOut: 10 }, 'claude-opus-5': { in: 5, out: 25, cacheRead: 0.5, cacheWrite5m: 6.25, cacheWrite1h: 10 }, 'claude-opus-4-8': { in: 5, out: 25, cacheRead: 0.5, cacheWrite5m: 6.25, cacheWrite1h: 10 } }
export function usdForUsage(model: string, u: Anthropic.Beta.BetaUsage): { usd: number; priced: boolean }
export function normalizeUsage(u: Anthropic.Beta.BetaUsage): NormalizedUsage

export interface LoopOptions { maxRepairs?: number /* 2 */; maxCalls?: number /* 12 */; tools?: PlannerTool[] /* [] disables tools */; maxTokens?: number /* 16000 */; onTurn?: (turn: Turn, index: number) => Promise<void> | void /* plan() logs cost here, so a later crash still has entries */; signal?: AbortSignal }
